// Prepare a valid, writable parent directory by reusing the directory of a fuzzer-provided file.
const char *base_path = FUZZ_PARAM_FILENAME();
std::string base(base_path ? base_path : "");
size_t slash = base.rfind('/');
if (slash == std::string::npos || slash == 0) { FUZZ_BAIL(); }
std::string dir = base.substr(0, slash);

// Generate a safe filename component. Sanitize to avoid separators and empties.
std::string raw = FUZZ_PARAM_STR();
if (raw.size() > 64) raw.resize(64);
for (char &c : raw) { if (c == '/' || c == '\\' || c == '\0') c = '_'; }
if (raw.empty()) raw = "node";
std::string path = dir + "/" + raw;

// Choose a file type we can create without special privileges: S_IFREG or S_IFIFO.
unsigned int pick = *FUZZ_PARAM(unsigned int) & 1u;
mode_t type = pick ? S_IFIFO : S_IFREG;
// Combine with random permission bits (respecting typical 0777 mask). Avoid sticky/setuid to keep it simple.
mode_t perms = (mode_t)(*FUZZ_PARAM(unsigned int) & 0777);
mode_t mode = type | perms;

// dev is ignored for non-device types; pass 0.
dev_t dev = (dev_t)0;

// Best-effort pre-cleanup to avoid EEXIST.
::unlink(path.c_str());

// Call the target function.
int rc = ::mknod(path.c_str(), mode, dev);

// Optional simple post-condition: if creation succeeded, the path should exist; clean it up.
if (rc == 0) {
    // Cleanup so subsequent iterations aren't affected.
    ::unlink(path.c_str());
}

